package com.example.swisswallet

import com.example.core.recovery.RecoveryRequest
import com.example.swisswallet.data.aa.Abi
import com.example.swisswallet.data.aa.CoinbaseSmartAccount
import com.example.swisswallet.data.aa.Hex
import com.example.swisswallet.data.aa.RecoveryModule
import com.example.swisswallet.data.aa.RecoveryModuleBytecode
import com.example.swisswallet.data.aa.UserOperationHasher
import com.example.swisswallet.data.key.WebAuthnAssertion
import com.example.swisswallet.domain.aa.UserOperation
import com.example.swisswallet.domain.aa.WebAuthnSignature
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import org.web3j.crypto.Hash
import java.math.BigInteger
import java.security.KeyPairGenerator
import java.security.Signature
import java.security.spec.ECGenParameterSpec
import java.util.Base64

/**
 * Every encoding the app sends on-chain, compared byte-for-byte with **viem** (reference vectors
 * generated by contracts/vectors.cjs). The full flow (real Coinbase Smart Wallet + EntryPoint v0.6 +
 * SwissRecoveryModule) is also tested end-to-end in contracts/e2e.cjs.
 *
 * Run with: ./gradlew :swisswallet:testDebugUnitTest
 */
class CoinbaseAndRecoveryTest {

    private val x = ByteArray(32) { 0x11 }
    private val y = ByteArray(32) { 0x22 }
    private val g = listOf(
        "0x1000000000000000000000000000000000000001", "0x2000000000000000000000000000000000000002",
        "0x3000000000000000000000000000000000000003", "0x4000000000000000000000000000000000000004",
    )
    private val wallet = "0xA0Cf798816D4b9b9866b5330EEa46a18382f251e"

    private fun eq(expected: String, actual: ByteArray) = assertEquals(expected.lowercase(), Hex.of(actual).lowercase())

    @Test
    fun `module CREATE2 address matches the deployment`() {
        assertEquals(Viem.MODULE_ADDRESS, RecoveryModule.address)
        assertEquals(RecoveryModuleBytecode.EXPECTED_ADDRESS, RecoveryModule.address)
        assertEquals(RecoveryModuleBytecode.INIT_CODE_HASH, Hex.of(Hash.sha3(RecoveryModule.initCode)))
    }

    @Test
    fun `createAccount with passkey + module owners`() = eq(
        Viem.CREATE_ACCOUNT,
        CoinbaseSmartAccount.createAccountCall(
            listOf(CoinbaseSmartAccount.passkeyOwner(x, y), CoinbaseSmartAccount.addressOwner(RecoveryModule.address)),
            BigInteger.ZERO,
        ),
    )

    @Test
    fun `execute and executeBatch`() {
        eq(Viem.EXECUTE, Abi.encodeCall("execute(address,uint256,bytes)", Abi.Arg.Address(g[0]), Abi.Arg.Uint(7), Abi.Arg.Bytes(byteArrayOf(0x12, 0x34))))
        eq(
            Viem.EXECUTE_BATCH,
            Abi.encodeCall(
                "executeBatch((address,uint256,bytes)[])",
                Abi.Arg.TupleArray(
                    listOf(
                        Abi.Arg.Tuple(Abi.Arg.Address(g[0]), Abi.Arg.Uint(7), Abi.Arg.Bytes(byteArrayOf(0x12, 0x34))),
                        Abi.Arg.Tuple(Abi.Arg.Address(g[1]), Abi.Arg.Uint(0), Abi.Arg.Bytes(ByteArray(0))),
                    )
                ),
            ),
        )
    }

    @Test
    fun `recovery module calls`() {
        eq(Viem.SETUP_GUARDIANS, RecoveryModule.setupGuardians(g, 3, 30))
        eq(Viem.INITIATE_RECOVERY, RecoveryModule.initiateRecovery(wallet, x, y, BigInteger.ZERO, listOf(ByteArray(65) { 0xaa.toByte() }, ByteArray(65) { 0xbb.toByte() })))
    }

    @Test
    fun `signature wrapper and WebAuthn struct`() {
        eq(Viem.SIGNATURE_WRAPPER, CoinbaseSmartAccount.wrapSignature(1, ByteArray(65) { 0xcc.toByte() }))
        eq(
            Viem.WEB_AUTHN_AUTH,
            CoinbaseSmartAccount.encodeWebAuthn(WebAuthnSignature(ByteArray(37) { 1 }, "{\"type\":\"webauthn.get\"}", 23, 1, BigInteger.valueOf(5), BigInteger.valueOf(6))),
        )
    }

    @Test
    fun `userOpHash v0_6`() = eq(
        Viem.USER_OP_HASH_V06,
        UserOperationHasher.hash(
            UserOperation(
                wallet, BigInteger.valueOf(5), ByteArray(0), byteArrayOf(0x12, 0x34), BigInteger.valueOf(100000),
                BigInteger.valueOf(200000), BigInteger.valueOf(50000), BigInteger.valueOf(1000000000), BigInteger.valueOf(100000000),
                Hex.bytes("0xdeadbeef"),
            ),
            "0x5FF137D4b0FDCD49DcA30c7CF57E578a026d2789", 84532,
        ),
    )

    @Test
    fun `recovery hash signed by guardians`() = eq(
        Viem.RECOVERY_HASH,
        RecoveryRequest(wallet, x, y, BigInteger.ZERO, BigInteger.ONE, 84532, RecoveryModule.address, "t").hash(),
    )

    @Test
    fun `WebAuthn assertion is what webauthn-sol expects`() {
        val kp = KeyPairGenerator.getInstance("EC").apply { initialize(ECGenParameterSpec("secp256r1")) }.generateKeyPair()
        val challenge = ByteArray(32) { it.toByte() }
        val sig = WebAuthnAssertion.build(challenge) { msg ->
            Signature.getInstance("SHA256withECDSA").run { initSign(kp.private); update(msg); sign() }
        }
        val json = sig.clientDataJSON
        // type / challenge at the declared indices
        assertTrue(json.startsWith("\"type\":\"webauthn.get\"", sig.typeIndex))
        val b64 = Base64.getUrlEncoder().withoutPadding().encodeToString(challenge)
        assertTrue(json.startsWith("\"challenge\":\"$b64\"", sig.challengeIndex))
        // flags: user present (0x01)
        assertTrue(sig.authenticatorData[32].toInt() and 0x01 == 1)
        // low-s
        assertTrue(sig.s <= WebAuthnAssertion.P256_N.shiftRight(1))
        // the signature verifies over authenticatorData ‖ sha256(clientDataJSON)
        val message = sig.authenticatorData + WebAuthnAssertion.sha256(json.toByteArray())
        val der = derOf(sig.r, sig.s)
        assertTrue(Signature.getInstance("SHA256withECDSA").run { initVerify(kp.public); update(message); verify(der) })
    }

    private fun derOf(r: BigInteger, s: BigInteger): ByteArray {
        fun int(v: BigInteger): ByteArray { val b = v.toByteArray(); return byteArrayOf(0x02, b.size.toByte()) + b }
        val body = int(r) + int(s)
        return byteArrayOf(0x30, body.size.toByte()) + body
    }

    /** Reference values computed with viem 2.21 (contracts/vectors.cjs). */
    private object Viem {
        const val MODULE_ADDRESS =
            "0xB3786e6BdB300575df7b5b3291E387a6f287428F"
        const val CREATE_ACCOUNT =
            ""
        const val EXECUTE =
            ""
        const val EXECUTE_BATCH =
            ""
        const val SETUP_GUARDIANS =
            ""
        const val INITIATE_RECOVERY =
            ""
        const val SIGNATURE_WRAPPER =
            ""
        const val WEB_AUTHN_AUTH =
            ""
        const val USER_OP_HASH_V06 =
            "0xe8b4521ae51163ba548aa6d3f2ff43d905b4e8b79268becd474fdac248b76f82"
        const val RECOVERY_HASH =
            "0x697249ba82ddddc0b4e4d6c165d6c2208365b7c2965d6576fb73770443f2a5a8"
    }
}
